{
  "didatica": [
    {
      "campo": "resolucao.antes.texto",
      "depois": "Durante a República, Roma conquistou muitos territórios. A maior parte das terras tomadas ficou com poucos ricos, que formaram grandes propriedades (latifúndios) trabalhadas por escravizados de guerra. Os pequenos camponeses também serviam como soldados. Ficavam anos longe de casa, endividavam-se e perdiam suas terras.",
      "motivo": "Frases mais curtas e sem a expressão 'na prática', que é vaga."
    },
    {
      "campo": "resolucao.antes.simbolos",
      "depois": [
        ["camponês-proprietário-soldado", "pequeno dono de terra que também lutava no exército da República"],
        ["República", "regime romano de 509 a.C. a 27 a.C., governado por magistrados (autoridades eleitas) e pelo Senado"],
        ["latifúndio", "grande propriedade rural: poucos donos ficam com muita terra"],
        ["excludente", "que deixa grupos de fora; aqui, os pequenos camponeses ficam sem acesso à terra"],
        ["desdobramento", "consequência, efeito que vem depois de um fato"],
        ["arruinar", "levar à falência, fazer perder tudo"],
        ["excerto", "trecho de um texto maior"],
        ["tribuno", "autoridade romana eleita para defender os interesses da plebe (povo comum)"],
        ["triunvirato", "aliança de três chefes que dividiam o poder"]
      ],
      "motivo": "Termos difíceis do enunciado e das alternativas (desdobramento, arruinar, excerto, tribuno, triunvirato) não estavam explicados."
    },
    {
      "campo": "resolucao.pista",
      "depois": "Pense num pequeno agricultor que passa anos na guerra enquanto as terras conquistadas vão para outros. O que acontece com ele? Procure a alternativa que descreve esse resultado.",
      "motivo": "Mais simples; mantém a ideia sem entregar a resposta."
    },
    {
      "campo": "resolucao.passos[0].porque",
      "depois": "O comando pede o que a conquista causou. A resposta deve estar no excerto, não ser qualquer fato de Roma.",
      "motivo": "Frase mais direta."
    },
    {
      "campo": "resolucao.passos[3].conta",
      "depois": "terra concentrada + camponês arruinado = terra em poucas mãos e pobres sem terra",
      "motivo": "A conta mostrava só o esquema; agora diz o resultado do processo."
    },
    {
      "campo": "resolucao.passos[4].porque",
      "depois": "Exército profissional, reforma agrária, assalariados, cavaleiros, triunvirato e pão e circo existem na história romana. Mas nenhum está no excerto, que fala só de terra e camponeses.",
      "motivo": "Deixa claro que o critério é o texto, não a veracidade do fato."
    },
    {
      "campo": "resolucao.erradas.C",
      "depois": "O excerto não fala de reforma agrária nem de ascensão da plebe. Os tribunos Tibério e Caio Graco propuseram reformas, mas foram mortos e a concentração de terras continuou. O texto diz que os camponeses foram arruinados, o contrário de subir na vida.",
      "motivo": "Mais claro; quem marcou C vê o que faltou: ler o 'arruinado' do texto."
    },
    {
      "campo": "resolucao.erradas.D",
      "depois": "O excerto não cita mão de obra assalariada nem cavaleiros. Nas grandes propriedades, o trabalho passou a ser escravo, não assalariado. Quem marcou D trouxe conhecimento de fora, sem apoio no texto.",
      "motivo": "Diz o que faltou no raciocínio de quem marcou D."
    },
    {
      "campo": "resolucao.erradas.E",
      "depois": "Triunvirato e pão e circo são fatos reais, mas o excerto não trata de generais nem de poder político. Ele trata da situação social e econômica dos camponeses. Quem marcou E respondeu sobre Roma em geral, e não sobre o texto.",
      "motivo": "Explicita o erro de raciocínio."
    },
    {
      "campo": "resolucao.visual.roteiro",
      "depois": "Quadro 1: mapa de Roma com setas de conquista. Quadro 2: terras conquistadas vão para poucos ricos e formam latifúndios com escravizados. Quadro 3: o camponês-soldado volta da guerra endividado e perde a terra. Quadro 4: sem terra, ele vai para a cidade e a desigualdade social cresce.",
      "motivo": "Frases mais curtas."
    }
  ],
  "didatica_alertas": [
    "A classificação do banco está como H01.7 (nível 6), enquanto a resolução usa H03.3 (nível 5). Conferir qual vale.",
    "O trecho 'excerto' diz que os camponeses foram impedidos de colher os frutos da vitória; a resolução diz 'foram à falência', o que simplifica um pouco, mas não muda o fato."
  ],
  "didatica_ok": true
}
